use std::cell::RefCell;
use std::collections::HashMap;
use std::io::{self, Read, Write};
use std::rc::Rc;

const RESERVED: &[&str] = &[
    "define", "set!", "lambda", "let", "if", "begin", "while", "and", "or", "not", "print", "+", "*",
    "-", "/", "%", "<", ">", "<=", ">=", "=",
];

const LIMIT: i128 = 1_000_000_000_000_000;
const MAX_STEPS: u64 = 200_000;
const MAX_DEPTH: usize = 100;

fn is_reserved(s: &str) -> bool {
    RESERVED.contains(&s)
}

#[derive(Clone)]
enum Expr {
    Int(i64),
    Bool(bool),
    Sym(String, usize),
    List(Rc<Vec<Expr>>, usize),
}

type EnvRef = Rc<RefCell<Env>>;

struct Env {
    vars: HashMap<String, Value>,
    parent: Option<EnvRef>,
}

struct Closure {
    params: Vec<String>,
    body: Rc<Vec<Expr>>,
    env: EnvRef,
}

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    Closure(Rc<Closure>),
}

struct Fail {
    line: usize,
    msg: String,
}

type R<T> = Result<T, Fail>;

fn fail<T>(line: usize, msg: &str) -> R<T> {
    Err(Fail { line, msg: msg.to_string() })
}

fn bad<T>(line: usize) -> R<T> {
    fail(line, "bad syntax")
}

fn check(v: i128, line: usize) -> R<i128> {
    if v.abs() > LIMIT {
        fail(line, "overflow")
    } else {
        Ok(v)
    }
}

fn show(v: &Value) -> String {
    match v {
        Value::Int(n) => n.to_string(),
        Value::Bool(true) => "#t".to_string(),
        Value::Bool(false) => "#f".to_string(),
        Value::Closure(_) => "<closure>".to_string(),
    }
}

// ---------- parsing ----------

fn atom(word: &str, line: usize) -> Result<Expr, (usize, String)> {
    match word {
        "#t" => return Ok(Expr::Bool(true)),
        "#f" => return Ok(Expr::Bool(false)),
        _ => {}
    }
    let digits = word.strip_prefix('-').unwrap_or(word);
    if !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()) {
        if digits.len() > 15 {
            return Err((line, "number too large".to_string()));
        }
        let v: i64 = digits.parse().unwrap();
        return Ok(Expr::Int(if word.starts_with('-') { -v } else { v }));
    }
    Ok(Expr::Sym(word.to_string(), line))
}

fn push_expr(stack: &mut Vec<(usize, Vec<Expr>)>, top: &mut Vec<Expr>, e: Expr) {
    match stack.last_mut() {
        Some((_, items)) => items.push(e),
        None => top.push(e),
    }
}

fn parse(src: &str) -> Result<Vec<Expr>, (usize, String)> {
    let chars: Vec<char> = src.chars().collect();
    let mut stack: Vec<(usize, Vec<Expr>)> = Vec::new();
    let mut top: Vec<Expr> = Vec::new();
    let mut line = 1usize;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\n' {
            line += 1;
            i += 1;
        } else if c.is_whitespace() {
            i += 1;
        } else if c == ';' {
            while i < chars.len() && chars[i] != '\n' {
                i += 1;
            }
        } else if c == '(' {
            stack.push((line, Vec::new()));
            i += 1;
        } else if c == ')' {
            let (l, items) = match stack.pop() {
                Some(x) => x,
                None => return Err((line, "unexpected )".to_string())),
            };
            push_expr(&mut stack, &mut top, Expr::List(Rc::new(items), l));
            i += 1;
        } else {
            let start = i;
            while i < chars.len() && !chars[i].is_whitespace() && !"();".contains(chars[i]) {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            let e = atom(&word, line)?;
            push_expr(&mut stack, &mut top, e);
        }
    }
    if let Some((l, _)) = stack.first() {
        return Err((*l, "unclosed (".to_string()));
    }
    Ok(top)
}

// ---------- environments ----------

fn lookup(env: &EnvRef, name: &str) -> Option<Value> {
    let mut cur = env.clone();
    loop {
        let next = {
            let b = cur.borrow();
            if let Some(v) = b.vars.get(name) {
                return Some(v.clone());
            }
            match &b.parent {
                Some(p) => p.clone(),
                None => return None,
            }
        };
        cur = next;
    }
}

fn assign(env: &EnvRef, name: &str, v: Value) -> Option<Value> {
    let mut cur = env.clone();
    loop {
        let next = {
            let mut b = cur.borrow_mut();
            if let Some(slot) = b.vars.get_mut(name) {
                return Some(std::mem::replace(slot, v));
            }
            match &b.parent {
                Some(p) => p.clone(),
                None => return None,
            }
        };
        cur = next;
    }
}

fn parse_params(e: &Expr) -> Option<Vec<String>> {
    let ps = match e {
        Expr::List(ps, _) => ps,
        _ => return None,
    };
    let mut names: Vec<String> = Vec::new();
    for p in ps.iter() {
        match p {
            Expr::Sym(s, _) if !is_reserved(s) && !names.contains(s) => names.push(s.clone()),
            _ => return None,
        }
    }
    Some(names)
}

// ---------- evaluation ----------

struct Interp {
    steps: u64,
    depth: usize,
    out: String,
}

impl Interp {
    fn eval(&mut self, e: &Expr, env: &EnvRef) -> R<Value> {
        match e {
            Expr::Int(n) => Ok(Value::Int(*n)),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Sym(name, line) => match lookup(env, name) {
                Some(v) => Ok(v),
                None => fail(*line, &format!("unbound variable {}", name)),
            },
            Expr::List(items, line) => self.eval_list(items, *line, env),
        }
    }

    fn eval_list(&mut self, items: &[Expr], line: usize, env: &EnvRef) -> R<Value> {
        self.steps += 1;
        if self.steps > MAX_STEPS {
            return fail(line, "step limit");
        }
        if items.is_empty() {
            return bad(line);
        }
        if let Expr::Sym(name, _) = &items[0] {
            match name.as_str() {
                "define" => {
                    if items.len() != 3 {
                        return bad(line);
                    }
                    let name = match &items[1] {
                        Expr::Sym(s, _) if !is_reserved(s) => s.clone(),
                        _ => return bad(line),
                    };
                    let v = self.eval(&items[2], env)?;
                    env.borrow_mut().vars.insert(name, v);
                    Ok(Value::Int(0))
                }
                "set!" => {
                    if items.len() != 3 {
                        return bad(line);
                    }
                    let (name, nline) = match &items[1] {
                        Expr::Sym(s, l) if !is_reserved(s) => (s.clone(), *l),
                        _ => return bad(line),
                    };
                    let v = self.eval(&items[2], env)?;
                    match assign(env, &name, v) {
                        Some(old) => Ok(old),
                        None => fail(nline, &format!("unbound variable {}", name)),
                    }
                }
                "lambda" => {
                    if items.len() < 3 {
                        return bad(line);
                    }
                    let params = match parse_params(&items[1]) {
                        Some(p) => p,
                        None => return bad(line),
                    };
                    let body = Rc::new(items[2..].to_vec());
                    Ok(Value::Closure(Rc::new(Closure { params, body, env: env.clone() })))
                }
                "let" => {
                    if items.len() < 3 {
                        return bad(line);
                    }
                    let binds = match &items[1] {
                        Expr::List(bs, _) => bs,
                        _ => return bad(line),
                    };
                    let mut names: Vec<String> = Vec::new();
                    let mut inits: Vec<&Expr> = Vec::new();
                    for b in binds.iter() {
                        let pair = match b {
                            Expr::List(p, _) if p.len() == 2 => p,
                            _ => return bad(line),
                        };
                        match &pair[0] {
                            Expr::Sym(s, _) if !is_reserved(s) && !names.contains(s) => {
                                names.push(s.clone());
                                inits.push(&pair[1]);
                            }
                            _ => return bad(line),
                        }
                    }
                    let mut vals = Vec::with_capacity(inits.len());
                    for &e in &inits {
                        vals.push(self.eval(e, env)?);
                    }
                    let vars: HashMap<String, Value> = names.into_iter().zip(vals).collect();
                    let new_env = Rc::new(RefCell::new(Env { vars, parent: Some(env.clone()) }));
                    let mut last = Value::Int(0);
                    for e in &items[2..] {
                        last = self.eval(e, &new_env)?;
                    }
                    Ok(last)
                }
                "if" => {
                    if items.len() != 3 && items.len() != 4 {
                        return bad(line);
                    }
                    let b = match self.eval(&items[1], env)? {
                        Value::Bool(b) => b,
                        _ => return fail(line, "type error"),
                    };
                    if b {
                        self.eval(&items[2], env)
                    } else if items.len() == 4 {
                        self.eval(&items[3], env)
                    } else {
                        Ok(Value::Int(0))
                    }
                }
                "begin" => {
                    let mut last = Value::Int(0);
                    for e in &items[1..] {
                        last = self.eval(e, env)?;
                    }
                    Ok(last)
                }
                "while" => {
                    if items.len() < 3 {
                        return bad(line);
                    }
                    loop {
                        match self.eval(&items[1], env)? {
                            Value::Bool(true) => {}
                            Value::Bool(false) => break,
                            _ => return fail(line, "type error"),
                        }
                        for e in &items[2..] {
                            self.eval(e, env)?;
                        }
                    }
                    Ok(Value::Int(0))
                }
                "and" | "or" => {
                    let is_and = name == "and";
                    for e in &items[1..] {
                        let b = match self.eval(e, env)? {
                            Value::Bool(b) => b,
                            _ => return fail(line, "type error"),
                        };
                        if is_and && !b {
                            return Ok(Value::Bool(false));
                        }
                        if !is_and && b {
                            return Ok(Value::Bool(true));
                        }
                    }
                    Ok(Value::Bool(is_and))
                }
                "not" => {
                    if items.len() != 2 {
                        return bad(line);
                    }
                    match self.eval(&items[1], env)? {
                        Value::Bool(b) => Ok(Value::Bool(!b)),
                        _ => fail(line, "type error"),
                    }
                }
                "print" => {
                    if items.len() != 2 {
                        return bad(line);
                    }
                    let v = self.eval(&items[1], env)?;
                    self.out.push_str(&show(&v));
                    self.out.push('\n');
                    Ok(Value::Int(0))
                }
                "+" | "*" | "-" | "/" | "%" | "<" | ">" | "<=" | ">=" | "=" => {
                    self.prim(name.as_str(), items, line, env)
                }
                _ => self.call(items, line, env),
            }
        } else {
            self.call(items, line, env)
        }
    }

    fn prim(&mut self, op: &str, items: &[Expr], line: usize, env: &EnvRef) -> R<Value> {
        let nargs = items.len() - 1;
        let arity_ok = match op {
            "-" => nargs >= 1,
            "/" | "%" | "<" | ">" | "<=" | ">=" | "=" => nargs == 2,
            _ => true,
        };
        if !arity_ok {
            return bad(line);
        }
        let mut vals = Vec::with_capacity(nargs);
        for a in &items[1..] {
            vals.push(self.eval(a, env)?);
        }
        let mut nums: Vec<i128> = Vec::with_capacity(nargs);
        for v in &vals {
            match v {
                Value::Int(n) => nums.push(*n as i128),
                _ => return fail(line, "type error"),
            }
        }
        let r = match op {
            "+" => {
                let mut acc = 0i128;
                for n in nums {
                    acc = check(acc + n, line)?;
                }
                acc
            }
            "*" => {
                let mut acc = 1i128;
                for n in nums {
                    acc = check(acc * n, line)?;
                }
                acc
            }
            "-" => {
                if nums.len() == 1 {
                    -nums[0]
                } else {
                    let mut acc = nums[0];
                    for n in &nums[1..] {
                        acc = check(acc - *n, line)?;
                    }
                    acc
                }
            }
            "/" | "%" => {
                if nums[1] == 0 {
                    return fail(line, "division by zero");
                }
                if op == "/" {
                    nums[0] / nums[1]
                } else {
                    nums[0] % nums[1]
                }
            }
            _ => {
                let (a, b) = (nums[0], nums[1]);
                let r = match op {
                    "<" => a < b,
                    ">" => a > b,
                    "<=" => a <= b,
                    ">=" => a >= b,
                    _ => a == b,
                };
                return Ok(Value::Bool(r));
            }
        };
        Ok(Value::Int(check(r, line)? as i64))
    }

    fn call(&mut self, items: &[Expr], line: usize, env: &EnvRef) -> R<Value> {
        let clo = match self.eval(&items[0], env)? {
            Value::Closure(c) => c,
            _ => return fail(line, "not a function"),
        };
        let mut args = Vec::with_capacity(items.len() - 1);
        for a in &items[1..] {
            args.push(self.eval(a, env)?);
        }
        if args.len() != clo.params.len() {
            return fail(line, "wrong number of arguments");
        }
        if self.depth >= MAX_DEPTH {
            return fail(line, "stack overflow");
        }
        let vars: HashMap<String, Value> = clo.params.iter().cloned().zip(args).collect();
        let call_env = Rc::new(RefCell::new(Env { vars, parent: Some(clo.env.clone()) }));
        self.depth += 1;
        let mut last = Value::Int(0);
        for e in clo.body.iter() {
            last = self.eval(e, &call_env)?;
        }
        self.depth -= 1;
        Ok(last)
    }
}

fn run() -> i32 {
    let mut bytes = Vec::new();
    io::stdin().read_to_end(&mut bytes).unwrap();
    let src = String::from_utf8_lossy(&bytes);
    let forms = match parse(&src) {
        Ok(f) => f,
        Err((line, msg)) => {
            println!("parse error line {}: {}", line, msg);
            return 2;
        }
    };
    let global: EnvRef = Rc::new(RefCell::new(Env { vars: HashMap::new(), parent: None }));
    let mut it = Interp { steps: 0, depth: 0, out: String::new() };
    let mut code = 0;
    for f in &forms {
        if let Err(fl) = it.eval(f, &global) {
            it.out.push_str(&format!("error line {}: {}\n", fl.line, fl.msg));
            code = 1;
            break;
        }
    }
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(it.out.as_bytes()).unwrap();
    lock.flush().unwrap();
    code
}

fn main() {
    // Deeply nested forms recurse on the native stack, so run on a large one.
    let child = std::thread::Builder::new()
        .stack_size(256 << 20)
        .spawn(run)
        .unwrap();
    let code = child.join().unwrap_or(1);
    std::process::exit(code);
}

