                    match assign(env, &name, v) {
                        Some(old) => Ok(old),
                        None => fail(nline, &format!("unbound variable {}", name)),
                    }
                }
                "lambda" => {
                    if items.len() < 3 {
                        return bad(line);
                    }
                    let params = match parse_params(&items[1]) {
                        Some(p) => p,
                        None => return bad(line),
                    };
                    let body = Rc::new(items[2..].to_vec());
                    Ok(Value::Closure(Rc::new(Closure { params, body, env: env.clone() })))
                }
