                    let mut inits: Vec<&Expr> = Vec::new();
                    for b in binds.iter() {
                        let pair = match b {
                            Expr::List(p, _) if p.len() == 2 => p,
                            _ => return bad(line),
                        };
                        match &pair[0] {
                            Expr::Sym(s, _) if !is_reserved(s) && !names.contains(s) => {
                                names.push(s.clone());
                                inits.push(&pair[1]);
                            }
                            _ => return bad(line),
                        }
                    }
                    let mut vals = Vec::with_capacity(inits.len());
                    for &e in &inits {
                        vals.push(self.eval(e, env)?);
                    }
                    let vars: HashMap<String, Value> = names.into_iter().zip(vals).collect();
                    let new_env = Rc::new(RefCell::new(Env { vars, parent: Some(env.clone()) }));
                    let mut last = Value::Int(0);
                    for e in &items[2..] {
                        last = self.eval(e, &new_env)?;
                    }
                    Ok(last)
                }
                "if" => {
                    if items.len() != 3 && items.len() != 4 {
                        return bad(line);
                    }
                    let b = match self.eval(&items[1], env)? {
                        Value::Bool(b) => b,
                        _ => return fail(line, "type error"),
                    };
                    if b {
                        self.eval(&items[2], env)
                    } else if items.len() == 4 {
                        self.eval(&items[3], env)
                    } else {
                        Ok(Value::Int(0))
                    }
                }
                "begin" => {
                    let mut last = Value::Int(0);
                    for e in &items[1..] {
                        last = self.eval(e, env)?;
                    }
                    Ok(last)
                }
                "while" => {
                    if items.len() < 3 {
                        return bad(line);
                    }
                    loop {
                        match self.eval(&items[1], env)? {
                            Value::Bool(true) => {}
                            Value::Bool(false) => break,
                            _ => return fail(line, "type error"),
                        }
                        for e in &items[2..] {
                            self.eval(e, env)?;
                        }
                    }
                    Ok(Value::Int(0))
                }
                "and" | "or" => {
                    let is_and = name == "and";
                    for e in &items[1..] {
                        let b = match self.eval(e, env)? {
                            Value::Bool(b) => b,
                            _ => return fail(line, "type error"),
                        };
                        if is_and && !b {
                            return Ok(Value::Bool(false));
                        }
                        if !is_and && b {
                            return Ok(Value::Bool(true));
                        }
                    }
                    Ok(Value::Bool(is_and))
                }
                "not" => {
                    if items.len() != 2 {
                        return bad(line);
                    }
                    match self.eval(&items[1], env)? {
                        Value::Bool(b) => Ok(Value::Bool(!b)),
                        _ => fail(line, "type error"),
                    }
                }
                "print" => {
                    if items.len() != 2 {
                        return bad(line);
                    }
                    let v = self.eval(&items[1], env)?;
                    self.out.push_str(&show(&v));
                    self.out.push('\n');
                    Ok(Value::Int(0))
                }
                "+" | "*" | "-" | "/" | "%" | "<" | ">" | "<=" | ">=" | "=" => {
                    self.prim(name.as_str(), items, line, env)
                }
                _ => self.call(items, line, env),
            }
        } else {
            self.call(items, line, env)
        }
    }

    fn prim(&mut self, op: &str, items: &[Expr], line: usize, env: &EnvRef) -> R<Value> {
        let nargs = items.len() - 1;
        let arity_ok = match op {
            "-" => nargs >= 1,
            "/" | "%" | "<" | ">" | "<=" | ">=" | "=" => nargs == 2,
            _ => true,
        };
        if !arity_ok {
            return bad(line);
        }
        let mut vals = Vec::with_capacity(nargs);
        for a in &items[1..] {
            vals.push(self.eval(a, env)?);
        }
        let mut nums: Vec<i128> = Vec::with_capacity(nargs);
        for v in &vals {
            match v {
                Value::Int(n) => nums.push(*n as i128),
                _ => return fail(line, "type error"),
            }
        }
        let r = match op {
            "+" => {
                let mut acc = 0i128;
                for n in nums {
                    acc = check(acc + n, line)?;
                }
                acc
            }
            "*" => {
                let mut acc = 1i128;
                for n in nums {
                    acc = check(acc * n, line)?;
                }
                acc
            }
            "-" => {
                if nums.len() == 1 {
                    -nums[0]
                } else {
                    let mut acc = nums[0];
                    for n in &nums[1..] {
                        acc = check(acc - *n, line)?;
                    }
                    acc
                }
            }
            "/" | "%" => {
                if nums[1] == 0 {
                    return fail(line, "division by zero");
                }
                if op == "/" {
                    nums[0] / nums[1]
                } else {
                    nums[0] % nums[1]
                }
            }
            _ => {
                let (a, b) = (nums[0], nums[1]);
                let r = match op {
                    "<" => a < b,
                    ">" => a > b,
                    "<=" => a <= b,
                    ">=" => a >= b,
                    _ => a == b,
                };
                return Ok(Value::Bool(r));
            }
        };
        Ok(Value::Int(check(r, line)? as i64))
    }

    fn call(&mut self, items: &[Expr], line: usize, env: &EnvRef) -> R<Value> {
        let clo = match self.eval(&items[0], env)? {
            Value::Closure(c) => c,
            _ => return fail(line, "not a function"),
        };
        let mut args = Vec::with_capacity(items.len() - 1);
        for a in &items[1..] {
            args.push(self.eval(a, env)?);
        }
        if args.len() != clo.params.len() {
            return fail(line, "wrong number of arguments");
        }
        if self.depth >= MAX_DEPTH {
            return fail(line, "stack overflow");
        }
        let vars: HashMap<String, Value> = clo.params.iter().cloned().zip(args).collect();
        let call_env = Rc::new(RefCell::new(Env { vars, parent: Some(clo.env.clone()) }));
        self.depth += 1;
        let mut last = Value::Int(0);
        for e in clo.body.iter() {
            last = self.eval(e, &call_env)?;
        }
        self.depth -= 1;
        Ok(last)
    }
}

fn run() -> i32 {
    let mut bytes = Vec::new();
    io::stdin().read_to_end(&mut bytes).unwrap();
    let src = String::from_utf8_lossy(&bytes);
    let forms = match parse(&src) {
        Ok(f) => f,
        Err((line, msg)) => {
            println!("parse error line {}: {}", line, msg);
            return 2;
        }
    };
    let global: EnvRef = Rc::new(RefCell::new(Env { vars: HashMap::new(), parent: None }));
    let mut it = Interp { steps: 0, depth: 0, out: String::new() };
    let mut code = 0;
    for f in &forms {
        if let Err(fl) = it.eval(f, &global) {
            it.out.push_str(&format!("error line {}: {}\n", fl.line, fl.msg));
            code = 1;
            break;
        }
    }
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(it.out.as_bytes()).unwrap();
    lock.flush().unwrap();
    code
}

fn main() {
    // Deeply nested forms recurse on the native stack, so run on a large one.
    let child = std::thread::Builder::new()
        .stack_size(256 << 20)
        .spawn(run)
        .unwrap();
    let code = child.join().unwrap_or(1);
    std::process::exit(code);
}
